def pi(s):
    p = [0] * len(s)
    for i in range(1, len(s) - 1):
        g = p[i - 1]
        while g and (s[i + 1] - s[i] != s[g + 1] - s[g]):
            g = p[g - 1]

        p[i] = g + int(s[i + 1] - s[i] == s[g + 1] - s[g])

    return p


def match(s, pat):
    res = 0
    p = pi(pat + [float('inf')] + s)
    for i in range(len(p) - len(s), len(p)):
        if p[i] == len(pat) - 1:
            res += 1

    return res


