def all_path_shortest(adj_list):
    src_to_dst = {node: defaultdict(lambda: float('inf')) for node in adj_list}

    for src in adj_list:
        for dest in adj_list[src]:
            src_to_dst[src][dest] = 1

    for src in adj_list:
        src_to_dst[src][src] = 0


    # Using node k, can we get from src to dest faster
