	if times == 0:
		return
	tmatrix = [[1,1,0],[1,1,1],[0,1,1]]
	for i in xrange(3):
		if v[i] > 0:
			tmatrix[0][i], tmatrix[1][i], tmatrix[2][i] = 0, 0, 0

	ans = [[1,0,0],[0,1,0],[0,0,1]]
	while times > 0:
		if times % 2 == 1:
			# ans = np.matmul(ans, tmatrix)
			mat(ans, tmatrix)
		# tmatrix = np.matmul(tmatrix, tmatrix)
		mat(tmatrix, tmatrix)
		times //= 2

